import re
P={}
def A(f,prefix,new): P.setdefault(f,[]).append((prefix,new))
A('p01',"La Revue Médicale Suisse donne la même définition","La Revue Médicale Suisse donne la même définition en français. L'anaphylaxie est une réaction d'hypersensibilité systémique, sévère et potentiellement fatale, qui survient brutalement après l'exposition à un allergène[@wb92728-13].")
A('p01',"La Revue Médicale Suisse décrit en effet","La Revue Médicale Suisse décrit en effet plusieurs atteintes des voies aériennes[@wb3abff-16]. Ce sont la dysphonie par œdème laryngé, la dysphagie par œdème pharyngé, le stridor inspiratoire et l'{{3|angiœdème}} de la langue[@wb3abff-16].")
A('p01',"La Revue Médicale Suisse inscrit pourtant","La Revue Médicale Suisse inscrit pourtant plusieurs diagnostics dans le différentiel[@wb3abff-22]. Ce sont l'asthme, les états de choc d'autre origine, l'inhalation d'un corps étranger, les attaques de panique, les malaises vagaux et les angiœdèmes liés à la bradykinine[@wb3abff-22].")
A('p02',"Les taux annuels de décès","Pour les médicaments, les taux annuels de décès vont de 0.05 à 0.51 par million de personnes[@wca55a0-12]. Ils vont de 0.03 à 0.32 pour les aliments et de 0.09 à 0.13 pour les venins[@wca55a0-12].")
A('p02',"Le délai médian avant un arrêt","Le délai médian avant un arrêt respiratoire ou cardiaque est de 5 minutes après un traitement injecté[@wb3abff-23]. Il est de 15 minutes après une piqûre d'hyménoptère et de 30 minutes après un aliment[@wb3abff-23].")
A('p02',"Dans la cohorte bernoise, 47.3","Dans la cohorte bernoise, 47.3 % des patients modérés à sévères ont reçu de l'adrénaline[@wac07fd-19]. La littérature rapporte une administration variant de 25 % à 70 %[@wac07fd-19].")
A('p02',"Les deux valeurs reposent","Les deux valeurs reposent sur la même série, c'est pourquoi l'étudiant retiendra l'ordre de grandeur plutôt qu'un chiffre unique[@wca55a0-47].")
A('p03',"L'allergie croisée est","L'allergie croisée est un sous-type de cette réaction[@wb92728-18]. Elle survient dès le premier contact, car un épitope commun existe entre l'allergène et un allergène précédent auquel l'organisme est déjà sensibilisé[@wb92728-18].")
A('p03',"Lors de l'effort physique","Lors de l'effort physique, une perméabilité digestive accrue fait passer l'allergène dans le plasma[@wb92728-16]. Il en résulte une dégranulation massive des mastocytes par des mécanismes impliquant des IgG[@wb92728-16].")
A('p03',">> 1 | Le syndrome du","Le syndrome du « ventricule vide » désigne le désamorçage de la pompe cardiaque lorsque le retour veineux s'effondre[@wb92728-27,wb3abff-27]. Le patient en choc doit donc rester allongé, de préférence en Trendelenburg, pour favoriser ce retour[@wb92728-27].")
A('p03',"L'atteinte des voies inférieures vient","L'atteinte des voies inférieures vient de la contraction du muscle lisse bronchique[@aips-53836-29]. L'adrénaline agit sur les récepteurs β, diminue ce tonus et soulage ainsi la dyspnée et le halètement[@aips-53836-29].")
A('p03',"De plus, le métabisulfite","Le métabisulfite de sodium de l'auto-injecteur Epipen peut rarement provoquer des réactions d'hypersensibilité sévères et des bronchospasmes[@aips-53836-15]. Il ne faut cependant jamais retarder l'adrénaline pour cette raison[@aips-53836-15].")
A('p03',"La Revue Médicale Suisse propose un dosage","La Revue Médicale Suisse propose un dosage précoce de la tryptase, puis une valeur basale au moins 24 heures après la résolution des symptômes[@wb92728-25].")
A('p04',"Dans la liste des diagnostics","Dans la liste des diagnostics de la situation, l'anaphylaxie porte le rang d'exclusion E1. Aucun autre diagnostic n'est aussi rapidement mortel ni aussi accessible à un traitement immédiat.")
A('p04',"Il repose sur des symptômes typiques","Il repose sur des symptômes typiques qui surviennent subitement et progressent après l'exposition à un allergène connu ou potentiel[@wb92728-20]. Un risque vital ou une symptomatologie digestive les accompagne[@wb92728-20].")
A('p04',"Parmi les maladies respiratoires","Parmi les maladies respiratoires, elle cite l'obstruction laryngée, trachéale ou bronchique par corps étranger[@we347ec-45]. Elle cite aussi le dysfonctionnement des cordes vocales, la laryngotrachéite aiguë et l'état de mal asthmatique sans atteinte d'autres organes[@we347ec-45].")
A('p04',"L'inhalation de corps étranger donne","L'inhalation de corps étranger donne une obstruction aiguë sans urticaire ni hypotension. La crise d'asthme donne des sibilances sans atteinte d'un autre organe. Enfin, la cause cardiaque ou embolique donne une dyspnée avec choc mais sans œdème des muqueuses.")
A('p05',"Les signes d'alarme de l'enfant","L'EAACI liste des signes d'alarme chez l'enfant et chez l'adulte[@we347ec-84,we347ec-89]. Ce sont la toux persistante, la respiration bruyante, les vertiges persistants, la voix rauque, la difficulté à avaler, la langue gonflée, la somnolence et le collapsus[@we347ec-84,we347ec-89].")
A('p06',"Un cas décrit par","Un cas décrit par la Revue Médicale Suisse montre des sibilances diffuses sans œdème des voies respiratoires supérieures ni stridor[@wb3abff-9]. La saturation est alors à 93 % à l'air ambiant et la fréquence cardiaque à 130 par minute[@wb3abff-9].")
A('p06',"Les signes respiratoires listés","Les recommandations françaises listent les signes respiratoires des voies inférieures[@w6b0a29-73]. Ce sont la polypnée ou la bradypnée, la dyspnée, la toux, le bronchospasme, la baisse du débit expiratoire de pointe et la difficulté à parler[@w6b0a29-73]. La cyanose et l'arrêt respiratoire marquent la gravité[@w6b0a29-73].")
A('p06',"Chez l'enfant, la tension systolique est basse","Chez l'enfant, la tension systolique est basse en dessous de 70 mmHg de 1 mois à 1 an[@we347ec-41]. Elle est basse en dessous de 70 mmHg plus 2 fois l'âge de 1 à 10 ans, et en dessous de 90 mmHg de 11 à 17 ans[@we347ec-41].")
A('p07',"Les signes fonctionnels sont la dyspnée","Les signes fonctionnels sont la dyspnée, la toux, la gêne thoracique et la difficulté à parler[@w6b0a29-73]. Les signes physiques sont la polypnée, les sibilances, la baisse du débit expiratoire de pointe et la cyanose dans les formes graves[@w6b0a29-73].")
A('p08',"Le premier critère est","Le premier critère est un début aigu, en quelques minutes à quelques heures, avec atteinte de la peau, des muqueuses ou des deux[@we347ec-39]. Il se traduit par une urticaire généralisée, un prurit, un flush ou un gonflement des lèvres, de la langue ou de la luette[@we347ec-39].")
A('p08',"Il doit s'y ajouter","Il doit s'y ajouter une atteinte respiratoire[@we347ec-39]. Elle comprend la dyspnée, les sibilances ou le bronchospasme, le stridor, la baisse du débit expiratoire de pointe et l'hypoxémie[@we347ec-39]. Une baisse de la tension avec dysfonction d'organe peut la remplacer, par hypotonie, syncope ou incontinence[@we347ec-39].")
A('p08',"Le deuxième critère demande","Le deuxième critère demande au moins 2 éléments parmi les suivants, survenant rapidement après l'exposition à un allergène probable pour ce patient[@we347ec-40]. Ce sont l'atteinte cutanéo-muqueuse, l'atteinte respiratoire, la baisse de la tension ou ses signes associés, et les symptômes digestifs persistants comme les douleurs crampiformes ou les vomissements[@we347ec-40].")
A('p08',"Chez le nourrisson et l'enfant","Chez le nourrisson et l'enfant, la tension systolique est basse en dessous de 70 mmHg de 1 mois à 1 an[@we347ec-41]. Elle est basse en dessous de 70 mmHg plus 2 fois l'âge de 1 à 10 ans[@we347ec-41]. Elle est aussi basse en dessous de 90 mmHg de 11 à 17 ans, ou diminuée de plus de 30 %[@we347ec-41].")
A('p08',"La Revue Médicale Suisse énonce","La Revue Médicale Suisse énonce qu'une anaphylaxie doit être évoquée devant des symptômes typiques et brutaux[@wb92728-20]. Ils progressent dans les minutes à heures après un allergène connu ou potentiel, avec un risque vital ou une symptomatologie digestive[@wb92728-20]. Le risque vital comprend l'atteinte des voies aériennes, les difficultés respiratoires et l'hypotension[@wb92728-20].")
A('p08',"Les critères de la cohorte bernoise","Les critères de la cohorte bernoise sont proches[@wca55a0-13]. Il faut des symptômes cutanés typiques et des symptômes significatifs dans au moins un autre organe[@wca55a0-13]. L'exposition à un allergène probable avec une atteinte respiratoire ou cardiovasculaire suffit aussi[@wca55a0-13].")
A('p08',"L'EAACI suggère de mesurer la tryptase","L'EAACI suggère de mesurer la tryptase tôt après le début de la réaction[@we347ec-33]. Elle suggère ensuite une valeur de base au moins 24 heures après la résolution complète[@we347ec-33].")
A('p09',"Les médiateurs de l'anaphylaxie peuvent","Les médiateurs de l'anaphylaxie peuvent induire un spasme coronarien, une rupture de plaque et une occlusion coronaire[@w6b0a29-58]. L'ECG réalisé le plus tôt possible contribue donc au diagnostic de syndrome coronarien aigu[@w6b0a29-58].")
A('p09',"La Revue Médicale Suisse propose un dosage","La Revue Médicale Suisse propose un dosage précoce de la tryptase, puis une valeur au moins 24 heures après la résolution des symptômes[@wb92728-25].")
A('p11',"L'adrénaline intramusculaire administrée","L'adrénaline intramusculaire administrée dans les plus brefs délais constitue la clé de voûte de la prise en charge initiale[@wb92728-40]. Elle s'associe à l'éviction de l'allergène et à la prise en charge des détresses vitales[@wb92728-40].")
A('p11',"La mortalité et les complications","La mortalité et les complications augmentent avec le délai avant l'adrénaline[@wb3abff-23]. Le but est donc une injection dès la reconnaissance, avant tout examen complémentaire[@wb3abff-25].")
A('p11',"L'Adrenalin Sintetica 1 mg/ml (Swissmedic 56551) est","L'Adrenalin Sintetica 1 mg/ml (Swissmedic 56551) est indiquée dans le choc anaphylactique[@aips-56551-0,aips-56551-1].")
A('p11',"Chez l'enfant, la notice donne","Chez l'enfant, la notice donne 0,5 mg au-delà de 12 ans et 0,3 mg de 6 à 12 ans[@aips-56551-5]. Elle donne 0,15 mg de 6 mois à 6 ans et 0,01 mg/kg en dessous de 6 mois[@aips-56551-5].")
A('p11',"Pour l'auto-injection, Epipen","Pour l'auto-injection, Epipen et Epipen Junior (Swissmedic 53836) donnent 0,3 mg au-dessus de 30 kg et 0,15 mg entre 15 et 30 kg[@aips-53836-0,aips-53836-3,aips-53836-4].")
A('p11',"Entre 7,5 et 15 kg","Entre 7,5 et 15 kg, l'utilisation d'Epipen Junior s'évalue au cas par cas[@aips-53836-4]. En dessous de 7,5 kg, elle n'est pas recommandée, sauf danger de mort sous surveillance médicale[@aips-53836-4].")
A('p11',"Jext (Swissmedic 61315)","Jext (Swissmedic 61315) donne 300 microgrammes au-dessus de 30 kg et 150 microgrammes entre 15 et 30 kg[@aips-61315-0,aips-61315-4].")
A('p11',"La conduite suivie est celle","La conduite suivie est celle de la notice, avec titration sous monitorage. Si une détresse vitale persiste, l'indication vitale prime sur les précautions[@aips-56551-8]. Le glucagon intraveineux est alors proposé en cas d'hypotension résistante[@wb92728-35].")
A('p11',"Tavegyl en solution injectable","Tavegyl en solution injectable (clémastine, Swissmedic 35501) est indiqué en traitement secondaire, après l'adrénaline intramusculaire, dans le choc anaphylactique et l'angiœdème[@aips-35501-0,aips-35501-1].")
A('p11',"La cétirizine orale","La cétirizine orale (Cetirizin Zentiva, Swissmedic 56329) est autorisée pour la rhinite allergique, la conjonctivite allergique et l'urticaire chronique idiopathique[@aips-56329-0,aips-56329-1]. La dose est de 10 mg une fois par jour chez l'adulte, mais l'anaphylaxie ne fait pas partie de l'indication[@aips-56329-3].")
A('p11',"Solu-Cortef (Swissmedic 23533) est","Solu-Cortef (Swissmedic 23533) est indiqué dans les affections allergiques aiguës, dont les réactions anaphylactiques, après l'administration d'adrénaline[@aips-23533-0,aips-23533-1].")
A('p11',"Les doses initiales peuvent","Les doses initiales peuvent aller jusqu'à 100 mg par voie intraveineuse en 30 secondes au minimum[@aips-23533-11]. Un traitement parentéral à haute dose ne dépasse généralement pas 48 à 72 heures[@aips-23533-8].")
A('p11',"La Revue Médicale Suisse cite plutôt","La Revue Médicale Suisse cite plutôt la méthylprednisolone par voie intraveineuse dans le choc[@wb92728-34]. La notice de Solu-Medrol (Swissmedic 35112) ne donne pas ce schéma pour l'anaphylaxie[@aips-35112-0]. La conduite suit donc Solu-Cortef.")
A('p11',"La notice de Prednisolone Streuli","La notice de Prednisolone Streuli (Swissmedic 29348) rappelle que le choc anaphylactique exige d'abord un corticostéroïde soluble par voie intraveineuse[@aips-29348-0,aips-29348-6].")
A('p11',"Pour le bronchospasme, Ventolin","Pour le bronchospasme, Ventolin (salbutamol, Swissmedic 37397) donne chez l'adulte et l'adolescent de plus de 12 ans 1 à 2 inhalations dans le bronchospasme aigu[@aips-37397-0,aips-37397-3].")
A('p11',"En cas de cardiopathie, de glaucome","En cas de cardiopathie, de glaucome à angle fermé ou d'hyperthyroïdie, les effets indésirables sévères sont fréquents[@aips-53836-8]. La réaction engageant le pronostic vital ne connaît pourtant pas de contre-indication absolue[@aips-53836-8].")
A('p11',"Chez le patient anticoagulé","Chez le patient anticoagulé, la voie intramusculaire est à éviter si possible, en raison du risque de saignement[@wb3abff-30]. Les recommandations françaises autorisent pourtant l'injection à la cuisse, même sous antithrombotiques[@w6b0a29-43].")
A('p11',"La Revue Médicale Suisse préconise","La Revue Médicale Suisse préconise une durée plus courte, sans consensus[@wb92728-28]. Elle propose de la prolonger si la réaction est importante ou si le suivi est incertain[@wb92728-28].")
A('p11',"Des facteurs imposent","Des facteurs imposent une observation prolongée chez le patient[@we347ec-77]. Ce sont l'asthme sévère, la présentation le soir ou la nuit, l'accès difficile aux soins et un antécédent de réaction biphasique[@we347ec-77]. Du côté de la réaction, ce sont l'atteinte multi-organes, la composante respiratoire sévère, plus d'une dose d'adrénaline et le déclencheur inconnu[@we347ec-78].")
A('p11',"Avant la sortie, l'EAACI demande","Avant la sortie, l'EAACI demande d'évaluer le risque de récidive[@we347ec-74]. Elle demande de prescrire des auto-injecteurs à ceux qui en ont besoin, avec des conseils écrits et une orientation vers l'allergologue[@we347ec-74,we347ec-75].")
A('p11',"La conduite retient le bolus","La conduite retient le bolus de 500 ml, répété selon la réponse, car il est prudent chez le patient cardiaque[@we347ec-72].")
A('p12',"L'étudiant retiendra que","La prévention primaire repose surtout sur la prudence avec les médicaments à risque[@wca55a0-26]. En effet, les antibiotiques β-lactamines, les anti-inflammatoires non stéroïdiens et les produits de contraste dominent parmi les déclencheurs médicamenteux[@we347ec-19,wca55a0-26].")
A('p12',"L'EAACI définit les indications absolues","L'EAACI définit les indications absolues d'un auto-injecteur[@we347ec-57]. Ce sont l'anaphylaxie antérieure déclenchée par un aliment, le latex ou un aéroallergène, l'anaphylaxie d'effort et l'anaphylaxie idiopathique[@we347ec-57]. Ce sont aussi l'asthme instable ou modéré à sévère avec allergie alimentaire, l'allergie aux venins avec réaction plus que cutanéo-muqueuse et la mastocytose systémique de l'adulte[@we347ec-58].")
A('p12',"L'EAACI recommande une formation structurée","L'EAACI recommande une formation structurée et complète des personnes à risque[@we347ec-93]. Cette formation s'ajoute aux instructions de base et améliore la reconnaissance de l'anaphylaxie et l'usage de l'auto-injecteur[@we347ec-93].")
for f,L in P.items():
    t=open(f'src/{f}.txt',encoding='utf-8').read()
    for pre,new in L:
        if pre.startswith('>> 1 |'):
            pat=re.escape(pre)+r'.*?\]\.'
            new='>> 1 | '+new
        else:
            pat=re.escape(pre)+r'.*?\]\.'
        m=re.search(pat,t,re.S)
        if not m: print('NOT FOUND',f,pre); continue
        t=t[:m.start()]+new+t[m.end():]
    open(f'src/{f}.txt','w',encoding='utf-8').write(t)
